CREATE OR REPLACE SEMANTIC VIEW "SEMABRIDGE"."COMPE_FINAL"."COMPETITIVE_MARKETING_ANALYSIS_SEMANTIC"
TABLES (
  CATEGORY AS "SEMABRIDGE"."COMPE_FINAL"."CATEGORY" PRIMARY KEY ("CATEGORY"),
  COL_DATE AS "SEMABRIDGE"."COMPE_FINAL"."DATE" PRIMARY KEY ("COL_DATE"),
  GEO AS "SEMABRIDGE"."COMPE_FINAL"."GEO" PRIMARY KEY ("ZIP"),
  INDICATORS AS "SEMABRIDGE"."COMPE_FINAL"."INDICATORS" PRIMARY KEY ("SORT"),
  KPI AS "SEMABRIDGE"."COMPE_FINAL"."KPI" PRIMARY KEY ("KPI"),
  MANUFACTURER AS "SEMABRIDGE"."COMPE_FINAL"."MANUFACTURER" PRIMARY KEY ("MANUFACTURERID"),
  PRODUCT AS "SEMABRIDGE"."COMPE_FINAL"."PRODUCT" PRIMARY KEY ("PRODUCTID"),
  SALESFACT AS "SEMABRIDGE"."COMPE_FINAL"."SALESFACT_ENRICHED",
  SENTIMENT AS "SEMABRIDGE"."COMPE_FINAL"."SENTIMENT_ENRICHED"
)
RELATIONSHIPS (
  PRODUCT_MANUFACTURERID_MANUFACTURER_MANUFACTURERID AS PRODUCT ("MANUFACTURERID") REFERENCES MANUFACTURER ("MANUFACTURERID"),
  SALESFACT_PRODUCTID_PRODUCT_PRODUCTID AS SALESFACT ("PRODUCTID") REFERENCES PRODUCT ("PRODUCTID"),
  SALESFACT_DATE_DATE_DATE AS SALESFACT ("COL_DATE") REFERENCES COL_DATE ("COL_DATE"),
  SALESFACT_ZIP_GEO_ZIP AS SALESFACT ("ZIP") REFERENCES GEO ("ZIP"),
  SENTIMENT_ZIP_GEO_ZIP AS SENTIMENT ("ZIP") REFERENCES GEO ("ZIP"),
  SENTIMENT_DATE_DATE_DATE AS SENTIMENT ("COL_DATE") REFERENCES COL_DATE ("COL_DATE"),
  SENTIMENT_MANUFACTURERID_MANUFACTURER_MANUFACTURERID AS SENTIMENT ("MANUFACTURERID") REFERENCES MANUFACTURER ("MANUFACTURERID"),
  PRODUCT_SEGMENT_CATEGORY_CATEGORY AS PRODUCT ("SEGMENT") REFERENCES CATEGORY ("CATEGORY")
)
DIMENSIONS (
  CATEGORY."CATEGORY" AS CATEGORY."CATEGORY",
  CATEGORY."CHANNEL" AS CATEGORY."CHANNEL",
  CATEGORY."SORT" AS CATEGORY."SORT",
  COL_DATE."COL_DATE" AS COL_DATE."COL_DATE",
  COL_DATE."MONTHNO" AS COL_DATE."MONTHNO",
  COL_DATE."MONTHNAME" AS COL_DATE."MONTHNAME",
  COL_DATE."MONTHID" AS COL_DATE."MONTHID",
  COL_DATE."MONTH" AS COL_DATE."MONTH",
  COL_DATE."QUARTER" AS COL_DATE."QUARTER",
  COL_DATE."YEAR" AS COL_DATE."YEAR",
  COL_DATE."RUNNINGMONTHS" AS COL_DATE."RUNNINGMONTHS",
  COL_DATE."RUNNING_YEAR" AS COL_DATE."RUNNING_YEAR",
  COL_DATE."ROLLING_PERIOD" AS COL_DATE."ROLLING_PERIOD",
  COL_DATE."ROLLING_PERIOD_SORT" AS COL_DATE."ROLLING_PERIOD_SORT",
  COL_DATE."MONTHINDEX" AS COL_DATE."MONTHINDEX",
  COL_DATE."MONTHS" AS COL_DATE."MONTHS",
  GEO."ZIP" AS GEO."ZIP",
  GEO."CITY" AS GEO."CITY",
  GEO."STATE" AS GEO."STATE",
  GEO."REGION" AS GEO."REGION",
  GEO."DISTRICT" AS GEO."DISTRICT",
  INDICATORS."SORT" AS INDICATORS."SORT",
  INDICATORS."STATUS" AS INDICATORS."STATUS",
  INDICATORS."IMAGE" AS INDICATORS."IMAGE",
  KPI."KPI" AS KPI."KPI",
  KPI."CATEGORY" AS KPI."CATEGORY",
  MANUFACTURER."MANUFACTURERID" AS MANUFACTURER."MANUFACTURERID",
  MANUFACTURER."MANUFACTURER" AS MANUFACTURER."MANUFACTURER",
  MANUFACTURER."MFGISVANARSDEL" AS MANUFACTURER."MFGISVANARSDEL",
  PRODUCT."MANUFACTURER" AS PRODUCT."MANUFACTURER",
  PRODUCT."CATEGORY" AS PRODUCT."CATEGORY",
  PRODUCT."SEGMENT" AS PRODUCT."SEGMENT",
  PRODUCT."PRODUCT" AS PRODUCT."PRODUCT",
  PRODUCT."PRODUCTID" AS PRODUCT."PRODUCTID",
  PRODUCT."ISVANARSDEL" AS PRODUCT."ISVANARSDEL",
  PRODUCT."ISCOMPETEHIDE" AS PRODUCT."ISCOMPETEHIDE",
  PRODUCT."MANUFACTURERID" AS PRODUCT."MANUFACTURERID",
  PRODUCT."ISCOMPETE" AS PRODUCT."ISCOMPETE",
  SALESFACT."PRODUCTID" AS SALESFACT."PRODUCTID",
  SALESFACT."COL_DATE" AS SALESFACT."COL_DATE",
  SALESFACT."ZIP" AS SALESFACT."ZIP",
  SALESFACT."UNITS" AS SALESFACT."UNITS",
  SALESFACT."REVENUE" AS SALESFACT."REVENUE",
  SENTIMENT."DATEID" AS SENTIMENT."DATEID",
  SENTIMENT."STATEID" AS SENTIMENT."STATEID",
  SENTIMENT."MANUFACTURERID" AS SENTIMENT."MANUFACTURERID",
  SENTIMENT."SCORE" AS SENTIMENT."SCORE",
  SENTIMENT."MANUFACTURER" AS SENTIMENT."MANUFACTURER",
  SENTIMENT."COL_DATE" AS SENTIMENT."COL_DATE",
  SENTIMENT."STATE" AS SENTIMENT."STATE",
  SENTIMENT."ZIP" AS SENTIMENT."ZIP",
  SENTIMENT."PRODUCTID" AS SENTIMENT."PRODUCTID",
  COL_DATE."RUNNING_MONTHS" AS COL_DATE."RUNNING_MONTHS",
  SALESFACT."IS_R12M" AS SALESFACT."IS_R12M",
  SALESFACT."IS_SPLY_YEAR" AS SALESFACT."IS_SPLY_YEAR",
  SALESFACT."IS_YTD" AS SALESFACT."IS_YTD",
  SALESFACT."IS_YTD_SPLY_YEAR" AS SALESFACT."IS_YTD_SPLY_YEAR",
  SALESFACT."MAX_DATE" AS SALESFACT."MAX_DATE",
  SALESFACT."PRODUCT_ISVANARSDEL" AS SALESFACT."PRODUCT_ISVANARSDEL",
  SENTIMENT."IS_R12M" AS SENTIMENT."IS_R12M",
  SENTIMENT."IS_SPLY_YEAR" AS SENTIMENT."IS_SPLY_YEAR",
  SENTIMENT."IS_YTD" AS SENTIMENT."IS_YTD",
  SENTIMENT."IS_YTD_SPLY_YEAR" AS SENTIMENT."IS_YTD_SPLY_YEAR",
  SENTIMENT."MANUFACTURER_MFGISVANARSDEL" AS SENTIMENT."MANUFACTURER_MFGISVANARSDEL",
  SENTIMENT."MAX_DATE" AS SENTIMENT."MAX_DATE"
)
METRICS (
  KPI."KPI01" AS CAST(NULL AS DOUBLE),
  KPI."KPI02" AS CAST(NULL AS DOUBLE),
  PRODUCT."COUNT_OF_PRODUCT" AS COUNT(PRODUCT.PRODUCT),
  PRODUCT."NEWCOUNT_OF_PRODUCT" AS COUNT_IF(PRODUCT."PRODUCT" IS NULL),
  PRODUCT."NEWNEWCOUNT_OF_PRODUCT" AS COUNT_IF(PRODUCT."PRODUCT" IS NULL),
  SALESFACT."TOTAL_UNITS" AS SUM(SALESFACT.UNITS::FLOAT),
  SALESFACT."SALES_DOL" AS SUM(SALESFACT.REVENUE::FLOAT),
  SENTIMENT."SENTIMENT" AS AVG(SENTIMENT.SCORE),
  SALESFACT."TOTAL_UNITS_YTD" AS SUM(CASE WHEN SALESFACT.IS_YTD THEN SALESFACT.UNITS ELSE NULL END::FLOAT),
  SALESFACT."TOTAL_VANARSDEL_UNITS_YTD" AS SUM(CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'Yes' THEN CASE WHEN SALESFACT.IS_YTD THEN SALESFACT.UNITS ELSE NULL END ELSE NULL END::FLOAT),
  SALESFACT."TOTAL_OTHER_UNITS_YTD" AS SUM(CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'No' THEN CASE WHEN SALESFACT.IS_YTD THEN SALESFACT.UNITS ELSE NULL END ELSE NULL END::FLOAT),
  SALESFACT."TOTAL_VANARSDEL_UNITS" AS SUM(CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END::FLOAT),
  SALESFACT."TOTAL_OTHER_UNITS" AS SUM(CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'No' THEN SALESFACT.UNITS ELSE NULL END::FLOAT),
  SALESFACT."PCT_UNITS_MARKET_SHARE" AS CASE WHEN (SUM(CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END::FLOAT)) = 0 THEN 0 ELSE IFF(COALESCE((SUM(SALESFACT.UNITS::FLOAT)), 0) = 0, 0, ((SUM(CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END::FLOAT))) / ((SUM(SALESFACT.UNITS::FLOAT)))) END,
  SALESFACT."TOTAL_CATEGORY_VOLUME" AS (SUM(SALESFACT.UNITS::FLOAT)),
  SALESFACT."TOTAL_COMPETE_VOLUME" AS SUM(CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'No' THEN SALESFACT.UNITS ELSE 0 END::FLOAT),
  SALESFACT."PCT_CATEGORY_COMPETE_SHARE" AS FLOOR(((SUM(CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'No' THEN SALESFACT.UNITS ELSE 0 END::FLOAT))) / NULLIF((SUM(SALESFACT.UNITS::FLOAT)), 0) * 100),
  SALESFACT."TOTAL_UNITS_SPLY" AS SUM(CASE WHEN SALESFACT.IS_SPLY_YEAR THEN SALESFACT.UNITS ELSE NULL END::FLOAT),
  SALESFACT."TOTAL_UNITS_YTD_SPLY" AS (SUM(CASE WHEN SALESFACT.IS_YTD_SPLY_YEAR THEN SALESFACT.UNITS ELSE NULL END::FLOAT)),
  SALESFACT."TOTAL_VANARSDEL_UNITS_YTD_SPLY" AS (SUM(CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'Yes' THEN CASE WHEN SALESFACT.IS_YTD_SPLY_YEAR THEN SALESFACT.UNITS ELSE NULL END ELSE NULL END::FLOAT)),
  SALESFACT."TOTAL_OTHER_UNITS_YTD_SPLY" AS (SUM(CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'No' THEN CASE WHEN SALESFACT.IS_YTD_SPLY_YEAR THEN SALESFACT.UNITS ELSE NULL END ELSE NULL END::FLOAT)),
  SALESFACT."PCT_UNITS_MARKET_SHARE_YTD" AS (SUM(CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'Yes' THEN CASE WHEN SALESFACT.IS_YTD THEN SALESFACT.UNITS ELSE NULL END ELSE NULL END::FLOAT)) / NULLIF((SUM(CASE WHEN SALESFACT.IS_YTD THEN SALESFACT.UNITS ELSE NULL END::FLOAT)), 0),
  SALESFACT."PCT_MARKET_SHARE_SPLY_YTD" AS ((SUM(CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'Yes' THEN CASE WHEN SALESFACT.IS_YTD_SPLY_YEAR THEN SALESFACT.UNITS ELSE NULL END ELSE NULL END::FLOAT)) / NULLIF((SUM(CASE WHEN SALESFACT.IS_YTD_SPLY_YEAR THEN SALESFACT.UNITS ELSE NULL END::FLOAT)), 0)),
  SALESFACT."PCT_UNIT_MARKET_SHARE_YOY_CHANGE" AS (CASE WHEN (SUM(CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END::FLOAT)) = 0 THEN 0 ELSE IFF(COALESCE((SUM(SALESFACT.UNITS::FLOAT)), 0) = 0, 0, ((SUM(CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END::FLOAT))) / ((SUM(SALESFACT.UNITS::FLOAT)))) END)-(CASE WHEN (SUM(CASE WHEN SALESFACT.IS_SPLY_YEAR THEN CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END ELSE NULL END::FLOAT)) = 0 THEN 0 ELSE IFF(COALESCE((SUM(CASE WHEN SALESFACT.IS_SPLY_YEAR THEN SALESFACT.UNITS ELSE NULL END::FLOAT)), 0) = 0, 0, ((SUM(CASE WHEN SALESFACT.IS_SPLY_YEAR THEN CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END ELSE NULL END::FLOAT))) / ((SUM(CASE WHEN SALESFACT.IS_SPLY_YEAR THEN SALESFACT.UNITS ELSE NULL END::FLOAT)))) END),
  SALESFACT."PCT_UNITS_MARKET_SHARE_SPLY" AS CASE WHEN (SUM(CASE WHEN SALESFACT.IS_SPLY_YEAR THEN CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END ELSE NULL END::FLOAT)) = 0 THEN 0 ELSE IFF(COALESCE((SUM(CASE WHEN SALESFACT.IS_SPLY_YEAR THEN SALESFACT.UNITS ELSE NULL END::FLOAT)), 0) = 0, 0, ((SUM(CASE WHEN SALESFACT.IS_SPLY_YEAR THEN CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END ELSE NULL END::FLOAT))) / ((SUM(CASE WHEN SALESFACT.IS_SPLY_YEAR THEN SALESFACT.UNITS ELSE NULL END::FLOAT)))) END,
  SALESFACT."TOTAL_UNITS_R12MS" AS SUM(CASE WHEN SALESFACT._CURRENT_FISCAL_PERIOD IS NOT NULL AND COL_DATE.MONTHINDEX <= SALESFACT._CURRENT_FISCAL_PERIOD AND COL_DATE.MONTHINDEX > SALESFACT._CURRENT_FISCAL_PERIOD - 12 THEN SALESFACT.UNITS::FLOAT ELSE 0 END::FLOAT),
  SALESFACT."TOTAL_VANARSDEL_UNITS_R12M" AS SUM(CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'Yes' THEN CASE WHEN SALESFACT._CURRENT_FISCAL_PERIOD IS NOT NULL AND COL_DATE.MONTHINDEX <= SALESFACT._CURRENT_FISCAL_PERIOD AND COL_DATE.MONTHINDEX > SALESFACT._CURRENT_FISCAL_PERIOD - 12 THEN SALESFACT.UNITS::FLOAT ELSE 0 END ELSE NULL END::FLOAT),
  SALESFACT."TOTAL_OTHER_UNITS_R12M" AS SUM(CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'No' THEN CASE WHEN SALESFACT._CURRENT_FISCAL_PERIOD IS NOT NULL AND COL_DATE.MONTHINDEX <= SALESFACT._CURRENT_FISCAL_PERIOD AND COL_DATE.MONTHINDEX > SALESFACT._CURRENT_FISCAL_PERIOD - 12 THEN SALESFACT.UNITS::FLOAT ELSE 0 END ELSE NULL END::FLOAT),
  SALESFACT."PCT_UNITS_MARKET_SHARE_R12M" AS CASE WHEN (SUM(CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'Yes' THEN CASE WHEN SALESFACT._CURRENT_FISCAL_PERIOD IS NOT NULL AND COL_DATE.MONTHINDEX <= SALESFACT._CURRENT_FISCAL_PERIOD AND COL_DATE.MONTHINDEX > SALESFACT._CURRENT_FISCAL_PERIOD - 12 THEN SALESFACT.UNITS::FLOAT ELSE 0 END ELSE NULL END::FLOAT)) = 0 THEN 0 ELSE IFF(COALESCE((SUM(CASE WHEN SALESFACT._CURRENT_FISCAL_PERIOD IS NOT NULL AND COL_DATE.MONTHINDEX <= SALESFACT._CURRENT_FISCAL_PERIOD AND COL_DATE.MONTHINDEX > SALESFACT._CURRENT_FISCAL_PERIOD - 12 THEN SALESFACT.UNITS::FLOAT ELSE 0 END::FLOAT)), 0) = 0, 0, ((SUM(CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'Yes' THEN CASE WHEN SALESFACT._CURRENT_FISCAL_PERIOD IS NOT NULL AND COL_DATE.MONTHINDEX <= SALESFACT._CURRENT_FISCAL_PERIOD AND COL_DATE.MONTHINDEX > SALESFACT._CURRENT_FISCAL_PERIOD - 12 THEN SALESFACT.UNITS::FLOAT ELSE 0 END ELSE NULL END::FLOAT))) / ((SUM(CASE WHEN SALESFACT._CURRENT_FISCAL_PERIOD IS NOT NULL AND COL_DATE.MONTHINDEX <= SALESFACT._CURRENT_FISCAL_PERIOD AND COL_DATE.MONTHINDEX > SALESFACT._CURRENT_FISCAL_PERIOD - 12 THEN SALESFACT.UNITS::FLOAT ELSE 0 END::FLOAT)))) END,
  SENTIMENT."SENTIMENT_GAP" AS CASE WHEN ((AVG(CASE WHEN SENTIMENT.MANUFACTURER_MFGISVANARSDEL = 'No' THEN SENTIMENT.SCORE ELSE NULL END) IS NULL)) OR ((AVG(CASE WHEN SENTIMENT.MANUFACTURER_MFGISVANARSDEL = 'Yes' THEN SENTIMENT.SCORE ELSE NULL END) IS NULL)) THEN NULL ELSE AVG(CASE WHEN SENTIMENT.MANUFACTURER_MFGISVANARSDEL = 'No' THEN SENTIMENT.SCORE ELSE NULL END) - AVG(CASE WHEN SENTIMENT.MANUFACTURER_MFGISVANARSDEL = 'Yes' THEN SENTIMENT.SCORE ELSE NULL END) END,
  SALESFACT."TOTAL_UNITS_YTD_VAR" AS (SUM(CASE WHEN SALESFACT.IS_YTD THEN SALESFACT.UNITS ELSE NULL END::FLOAT))-(SUM(CASE WHEN SALESFACT.IS_YTD_SPLY_YEAR THEN SALESFACT.UNITS ELSE NULL END::FLOAT)),
  SALESFACT."TOTAL_UNITS_YTD_VAR_PCT" AS ((SUM(CASE WHEN SALESFACT.IS_YTD THEN SALESFACT.UNITS ELSE NULL END::FLOAT))-(SUM(CASE WHEN SALESFACT.IS_YTD_SPLY_YEAR THEN SALESFACT.UNITS ELSE NULL END::FLOAT))) / NULLIF((SUM(CASE WHEN SALESFACT.IS_SPLY_YEAR THEN SALESFACT.UNITS ELSE NULL END::FLOAT)), 0),
  SALESFACT."SUM_OF_UNITS" AS SUM(SALESFACT.UNITS::FLOAT),
  SALESFACT."SUM_OF_REVENUE" AS SUM(SALESFACT.REVENUE::FLOAT),
  SALESFACT."ATINDICATOR01" AS CASE WHEN (FLOOR(((SUM(CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'No' THEN SALESFACT.UNITS ELSE 0 END::FLOAT))) / NULLIF((SUM(SALESFACT.UNITS::FLOAT)), 0) * 100)) < 0.55 THEN 1 ELSE CASE WHEN (FLOOR(((SUM(CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'No' THEN SALESFACT.UNITS ELSE 0 END::FLOAT))) / NULLIF((SUM(SALESFACT.UNITS::FLOAT)), 0) * 100)) > 0.6 THEN 3 ELSE 2 END END,
  SALESFACT."ATINDICATOR02" AS CASE WHEN ((CASE WHEN (SUM(CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END::FLOAT)) = 0 THEN 0 ELSE IFF(COALESCE((SUM(SALESFACT.UNITS::FLOAT)), 0) = 0, 0, ((SUM(CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END::FLOAT))) / ((SUM(SALESFACT.UNITS::FLOAT)))) END)-(CASE WHEN (SUM(CASE WHEN SALESFACT.IS_SPLY_YEAR THEN CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END ELSE NULL END::FLOAT)) = 0 THEN 0 ELSE IFF(COALESCE((SUM(CASE WHEN SALESFACT.IS_SPLY_YEAR THEN SALESFACT.UNITS ELSE NULL END::FLOAT)), 0) = 0, 0, ((SUM(CASE WHEN SALESFACT.IS_SPLY_YEAR THEN CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END ELSE NULL END::FLOAT))) / ((SUM(CASE WHEN SALESFACT.IS_SPLY_YEAR THEN SALESFACT.UNITS ELSE NULL END::FLOAT)))) END)) < 0 THEN 1 ELSE CASE WHEN ((CASE WHEN (SUM(CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END::FLOAT)) = 0 THEN 0 ELSE IFF(COALESCE((SUM(SALESFACT.UNITS::FLOAT)), 0) = 0, 0, ((SUM(CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END::FLOAT))) / ((SUM(SALESFACT.UNITS::FLOAT)))) END)-(CASE WHEN (SUM(CASE WHEN SALESFACT.IS_SPLY_YEAR THEN CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END ELSE NULL END::FLOAT)) = 0 THEN 0 ELSE IFF(COALESCE((SUM(CASE WHEN SALESFACT.IS_SPLY_YEAR THEN SALESFACT.UNITS ELSE NULL END::FLOAT)), 0) = 0, 0, ((SUM(CASE WHEN SALESFACT.IS_SPLY_YEAR THEN CASE WHEN SALESFACT.PRODUCT_ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END ELSE NULL END::FLOAT))) / ((SUM(CASE WHEN SALESFACT.IS_SPLY_YEAR THEN SALESFACT.UNITS ELSE NULL END::FLOAT)))) END)) > 0.2 THEN 3 ELSE 2 END END,
  SALESFACT."ATINDICATOR03" AS CASE WHEN (((SUM(CASE WHEN SALESFACT.IS_YTD THEN SALESFACT.UNITS ELSE NULL END::FLOAT))-(SUM(CASE WHEN SALESFACT.IS_YTD_SPLY_YEAR THEN SALESFACT.UNITS ELSE NULL END::FLOAT))) / NULLIF((SUM(CASE WHEN SALESFACT.IS_SPLY_YEAR THEN SALESFACT.UNITS ELSE NULL END::FLOAT)), 0)) < 0 THEN 1 ELSE CASE WHEN (((SUM(CASE WHEN SALESFACT.IS_YTD THEN SALESFACT.UNITS ELSE NULL END::FLOAT))-(SUM(CASE WHEN SALESFACT.IS_YTD_SPLY_YEAR THEN SALESFACT.UNITS ELSE NULL END::FLOAT))) / NULLIF((SUM(CASE WHEN SALESFACT.IS_SPLY_YEAR THEN SALESFACT.UNITS ELSE NULL END::FLOAT)), 0)) > 0.1 THEN 3 ELSE 2 END END,
  SENTIMENT."ATINDICATOR04" AS CASE WHEN (AVG(SENTIMENT.SCORE)) < 65 THEN 1 ELSE CASE WHEN (AVG(SENTIMENT.SCORE)) > 67 THEN 3 ELSE 2 END END,
  SENTIMENT."ATINDICATOR05" AS CASE WHEN (CASE WHEN ((AVG(CASE WHEN SENTIMENT.MANUFACTURER_MFGISVANARSDEL = 'No' THEN SENTIMENT.SCORE ELSE NULL END) IS NULL)) OR ((AVG(CASE WHEN SENTIMENT.MANUFACTURER_MFGISVANARSDEL = 'Yes' THEN SENTIMENT.SCORE ELSE NULL END) IS NULL)) THEN NULL ELSE AVG(CASE WHEN SENTIMENT.MANUFACTURER_MFGISVANARSDEL = 'No' THEN SENTIMENT.SCORE ELSE NULL END) - AVG(CASE WHEN SENTIMENT.MANUFACTURER_MFGISVANARSDEL = 'Yes' THEN SENTIMENT.SCORE ELSE NULL END) END) < 15 THEN 1 ELSE CASE WHEN (CASE WHEN ((AVG(CASE WHEN SENTIMENT.MANUFACTURER_MFGISVANARSDEL = 'No' THEN SENTIMENT.SCORE ELSE NULL END) IS NULL)) OR ((AVG(CASE WHEN SENTIMENT.MANUFACTURER_MFGISVANARSDEL = 'Yes' THEN SENTIMENT.SCORE ELSE NULL END) IS NULL)) THEN NULL ELSE AVG(CASE WHEN SENTIMENT.MANUFACTURER_MFGISVANARSDEL = 'No' THEN SENTIMENT.SCORE ELSE NULL END) - AVG(CASE WHEN SENTIMENT.MANUFACTURER_MFGISVANARSDEL = 'Yes' THEN SENTIMENT.SCORE ELSE NULL END) END) > 25 THEN 3 ELSE 2 END END,
  SENTIMENT."ATINDICATOR04A" AS CASE WHEN (CASE WHEN (AVG(SENTIMENT.SCORE)) < 65 THEN 1 ELSE CASE WHEN (AVG(SENTIMENT.SCORE)) > 67 THEN 3 ELSE 2 END END) = 1 THEN 'Low Sentiment Rate' ELSE CASE WHEN (CASE WHEN (AVG(SENTIMENT.SCORE)) < 65 THEN 1 ELSE CASE WHEN (AVG(SENTIMENT.SCORE)) > 67 THEN 3 ELSE 2 END END) = 3 THEN 'High Sentiment Rate' ELSE 'Medium Sentiment Rate' END END,
  SENTIMENT."ATINDICATOR05A" AS CASE WHEN (CASE WHEN (CASE WHEN ((AVG(CASE WHEN SENTIMENT.MANUFACTURER_MFGISVANARSDEL = 'No' THEN SENTIMENT.SCORE ELSE NULL END) IS NULL)) OR ((AVG(CASE WHEN SENTIMENT.MANUFACTURER_MFGISVANARSDEL = 'Yes' THEN SENTIMENT.SCORE ELSE NULL END) IS NULL)) THEN NULL ELSE AVG(CASE WHEN SENTIMENT.MANUFACTURER_MFGISVANARSDEL = 'No' THEN SENTIMENT.SCORE ELSE NULL END) - AVG(CASE WHEN SENTIMENT.MANUFACTURER_MFGISVANARSDEL = 'Yes' THEN SENTIMENT.SCORE ELSE NULL END) END) < 15 THEN 1 ELSE CASE WHEN (CASE WHEN ((AVG(CASE WHEN SENTIMENT.MANUFACTURER_MFGISVANARSDEL = 'No' THEN SENTIMENT.SCORE ELSE NULL END) IS NULL)) OR ((AVG(CASE WHEN SENTIMENT.MANUFACTURER_MFGISVANARSDEL = 'Yes' THEN SENTIMENT.SCORE ELSE NULL END) IS NULL)) THEN NULL ELSE AVG(CASE WHEN SENTIMENT.MANUFACTURER_MFGISVANARSDEL = 'No' THEN SENTIMENT.SCORE ELSE NULL END) - AVG(CASE WHEN SENTIMENT.MANUFACTURER_MFGISVANARSDEL = 'Yes' THEN SENTIMENT.SCORE ELSE NULL END) END) > 25 THEN 3 ELSE 2 END END) = 1 THEN 'Low Sentiment Gap' ELSE CASE WHEN (CASE WHEN (CASE WHEN ((AVG(CASE WHEN SENTIMENT.MANUFACTURER_MFGISVANARSDEL = 'No' THEN SENTIMENT.SCORE ELSE NULL END) IS NULL)) OR ((AVG(CASE WHEN SENTIMENT.MANUFACTURER_MFGISVANARSDEL = 'Yes' THEN SENTIMENT.SCORE ELSE NULL END) IS NULL)) THEN NULL ELSE AVG(CASE WHEN SENTIMENT.MANUFACTURER_MFGISVANARSDEL = 'No' THEN SENTIMENT.SCORE ELSE NULL END) - AVG(CASE WHEN SENTIMENT.MANUFACTURER_MFGISVANARSDEL = 'Yes' THEN SENTIMENT.SCORE ELSE NULL END) END) < 15 THEN 1 ELSE CASE WHEN (CASE WHEN ((AVG(CASE WHEN SENTIMENT.MANUFACTURER_MFGISVANARSDEL = 'No' THEN SENTIMENT.SCORE ELSE NULL END) IS NULL)) OR ((AVG(CASE WHEN SENTIMENT.MANUFACTURER_MFGISVANARSDEL = 'Yes' THEN SENTIMENT.SCORE ELSE NULL END) IS NULL)) THEN NULL ELSE AVG(CASE WHEN SENTIMENT.MANUFACTURER_MFGISVANARSDEL = 'No' THEN SENTIMENT.SCORE ELSE NULL END) - AVG(CASE WHEN SENTIMENT.MANUFACTURER_MFGISVANARSDEL = 'Yes' THEN SENTIMENT.SCORE ELSE NULL END) END) > 25 THEN 3 ELSE 2 END END) = 3 THEN 'High Sentiment Gap' ELSE 'Medium Sentiment Gap' END END,
  SALESFACT."TOTAL_UNITS_YTD_VAR_PCT2" AS FLOOR((((SUM(CASE WHEN SALESFACT.IS_YTD THEN SALESFACT.UNITS ELSE NULL END::FLOAT))-(SUM(CASE WHEN SALESFACT.IS_YTD_SPLY_YEAR THEN SALESFACT.UNITS ELSE NULL END::FLOAT)))) / NULLIF((SUM(CASE WHEN SALESFACT.IS_SPLY_YEAR THEN SALESFACT.UNITS ELSE NULL END::FLOAT)), 0) * 100),
  SENTIMENT."SUM_OF_SCORE" AS SUM(SENTIMENT.SCORE::FLOAT),
  SENTIMENT."AVERAGE_OF_SCORE" AS AVG(SENTIMENT.SCORE),
  SENTIMENT."NEW_DEMO_MEASURE" AS AVG(SENTIMENT.SCORE)
);